import {modules,sources,glossary} from './content.js';
import {renderPlanner,bindPlanner,plannerSources} from './planner.js';
const isPlanner=()=>/^#\/?planner(?:\/|$)/.test(location.hash);
import {renderExtendedActivity} from './extended-activities.js';
import {renderTaxActivity} from './tax-activities.js';
import {renderDebtActivity} from './debt-activities.js';
import {renderBenefitActivity} from './benefit-activities.js';
const learningModules=modules.filter(m=>m.kind!=='resource');
const resourceModules=modules.filter(m=>m.kind==='resource');
function renderFeatureActivity(name,a,money){return renderTaxActivity(name,a,money)??renderDebtActivity(name,a,money)??renderBenefitActivity(name,a,money)??renderExtendedActivity(name,a,money)}
import {repayment,futureValue,initialBudget} from './calculations.js';
const root=document.querySelector('#app');
const money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mode=(()=>{try{return sessionStorage.getItem('msq-mode')==='demo'?'demo':'workshop'}catch{return 'workshop'}})(),storageOK=true,storageWarning='',drawer=null,modal=null,playlist=false;
function empty(){return {schemaVersion:1,modules:{}}}
function load(){try{const raw=localStorage.getItem('money-side-quests:'+mode+':v1');if(!raw)return empty();const d=JSON.parse(raw);if(d.schemaVersion!==1||!d.modules||typeof d.modules!=='object'||Array.isArray(d.modules))throw Error();for(const [id,v] of Object.entries(d.modules)){if(!modules.some(m=>m.id===id)||!v||typeof v!=='object'||!v.steps||typeof v.steps!=='object'||Array.isArray(v.steps)||!v.activities||typeof v.activities!=='object'||Array.isArray(v.activities))throw Error();for(const x of Object.values(v.steps))if(!x||typeof x!=='object'||Array.isArray(x)||('answer' in x&&(!Number.isInteger(x.answer)||x.answer<0||x.answer>20)))throw Error();for(const a of Object.values(v.activities)){if(!a||typeof a!=='object'||Array.isArray(a))throw Error();for(const [key,value] of Object.entries(a)){if(key==='values'){if(!value||typeof value!=='object'||Object.entries(value).some(([k,n])=>!(k in initialBudget)||!Number.isFinite(n)||n<0||n>100000))throw Error()}else if(key==='scenario'){if(!['company','market','rally'].includes(value))throw Error()}else if(key==='fundA'||key==='fundB'){if(!['A','B','C','D'].includes(value))throw Error()}else if(key==='product'){if(!['etf','stock','bond','gic','crypto'].includes(value))throw Error()}else if(key==='jurisdiction'){if(!['ON','federal'].includes(value))throw Error()}else if(key==='account'){if(!['tfsa','rrsp','fhsa'].includes(value))throw Error()}else if(key==='loanType'){if(!['standard','mortgage'].includes(value))throw Error()}else if(key==='frequency'){if(![1,12].includes(value))throw Error()}else if(key==='shock'){if(typeof value!=='boolean')throw Error()}else if(!Number.isFinite(value)||value < (['gross','annualReturn'].includes(key)?-50:0)||value>10000000||(['years'].includes(key)&&(value<1||value>50))||(['rate','coupon','yield','inflation','spread','fx','mer'].includes(key)&&value>30))throw Error()}}}return d}catch{storageWarning='Saved progress could not be restored. This session starts fresh.';return empty()}}
let state=load();
function save(){try{localStorage.setItem('money-side-quests:'+mode+':v1',JSON.stringify({...state,savedAt:new Date().toISOString()}));storageOK=true}catch{storageOK=false}updateSave()}
function updateSave(){document.querySelectorAll('[data-save]').forEach(e=>e.textContent=storageOK?'Progress saved on this browser':'Progress stays in this session only')}
function mp(id){return state.modules[id]??=( {steps:{},activities:{},lastStep:0})}
function sp(m,s){return mp(m.id).steps[s.id]??={}}
function resumeIndex(id){const m=modules.find(x=>x.id===id),p=mp(id);let saved=p.lastStepId;if(!saved&&id==='investing'&&p.lastStep!==undefined)saved=['invest-start','invest-types','invest-goals','invest-risk','invest-check-1','invest-fees','invest-accounts','invest-check-2','invest-recap'][p.lastStep];const i=m.steps.findIndex(s=>s.id===saved);return i>=0?i:Math.min(p.lastStep??0,m.steps.length-1)}
function completed(m){return m.steps.filter(s=>mp(m.id).steps[s.id]?.completed).length}
function route(){const [id,idx]=location.hash.replace(/^#\/?/,'').split('/');const m=modules.find(x=>x.id===id);return {m,index:m?Math.min(Math.max(parseInt(idx)||0,0),m.steps.length-1):0}}
function go(id,index=0){location.hash=id?'/'+id+'/'+index:'/';if(location.hash==='#/'||route().m?.id===id)render();window.scrollTo(0,0)}
const icons={budgeting:'◴',credit:'▰',investing:'↗',accounts:'▤',borrowing:'⌂',benefits:'✳'};
function art(){return `<svg class="hero-art" viewBox="0 0 350 280" aria-hidden="true"><path d="M78 280V148a94 94 0 0 1 188 0v132" fill="#b2ce77"/><path d="M105 280V153a68 68 0 0 1 136 0v127" fill="#eff5d4"/><ellipse cx="189" cy="266" rx="120" ry="14" fill="#9ab961" opacity=".35"/><g transform="translate(94 156) rotate(-12)"><rect x="0" y="0" width="116" height="75" rx="10" fill="#6c5a9e"/><rect x="0" y="17" width="116" height="13" fill="#413454"/><rect x="14" y="44" width="24" height="15" rx="3" fill="#dccaa1"/><path d="M76 54h20" stroke="#cfbfe8" stroke-width="4"/></g><g transform="translate(224 162)"><path d="M10 48v-76M10 13C-35 9-32-22 10-9M10-7C53-15 51-45 10-30" stroke="#49694b" stroke-width="4" fill="#7e9e63"/><path d="M-12 44h47l-7 44H-5z" fill="#ca9871"/><path d="M-14 44h51v10h-51z" fill="#b78561"/></g><g transform="rotate(15 235 85)"><ellipse cx="235" cy="85" rx="29" ry="33" fill="#9f7c43"/><ellipse cx="230" cy="84" rx="27" ry="32" fill="#f2d88d"/><ellipse cx="230" cy="84" rx="20" ry="25" fill="none" stroke="#d7b76c" stroke-width="2"/><text x="230" y="96" text-anchor="middle" font-size="34" font-family="Georgia" fill="#a78743">$</text></g><path d="m58 103 7 10 12-22M284 55v17M276 63h16" stroke="#5b7545" stroke-width="3" fill="none"/><circle cx="295" cy="132" r="5" fill="#a2bb68"/><path d="m132 34 4 9 9 4-9 4-4 9-4-9-9-4 9-4z" fill="#f6fae5"/></svg>`}
function shell(content,m){return `<div class="shell"><aside class="sidebar"><a class="brand" href="#/"><span class="brandmark">↗</span><span>money<br>side quests<small>MAKE CENTS OF IT.</small></span></a><div class="navlabel">YOUR LEARNING SPACE</div><nav><button class="navitem ${!m?'active':''}" data-home><span class="nicon">▦</span>All modules</button>${learningModules.map(x=>`<button class="navitem ${m?.id===x.id?'active':''}" data-module="${x.id}"><span class="nicon">${icons[x.id]??"✦"}</span>${esc(x.title)}${completed(x)===x.steps.length?'<span class="tiny">✓</span>':''}</button>`).join('')}<div class="navlabel benefits-navlabel planner-tool-nav">TOOLS FOR REAL LIFE</div><button class="navitem ${isPlanner()?'active':''}" data-planner-open><span class="nicon">◉</span>Budget planner</button><div class="navlabel benefits-navlabel">BEYOND YOUR SALARY</div>${resourceModules.map(x=>`<button class="navitem ${m?.id===x.id?'active':''}" data-module="${x.id}"><span class="nicon">✳</span>${esc(x.title)}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note"><strong>A little wiser. A little freer.</strong>No perfect budgets. No silly questions. Just one money skill at a time.</div><div class="local"><i class="dot"></i><span ${isPlanner()?'':'data-save'}>${isPlanner()?'Budget stays on this browser':storageOK?'Progress saved on this browser':'Progress stays in this session only'}</span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Your money playground ${m?' / '+esc(m.title):''}</div><div class="top-actions"><span class="pill canada">🍁 CANADIAN EDITION</span><button class="plain" data-demo>${mode==='demo'?'Exit demo':'Demo mode'}</button><button class="plain reset-control" ${isPlanner()?'data-planner-reset':'data-reset="'+(m?m.id:'all')+'"'}>↺ ${isPlanner()?'Reset planner':m?'Reset module':'Reset lessons'}</button><button class="plain" data-drawer="glossary">Aa <span>Glossary</span></button></div></header>${mode==='demo'?'<div class="banner">Demo mode · Try anything. Your saved '+(isPlanner()?'budget':'workshop progress')+' is kept separately. <button class="plain" '+(isPlanner()?'data-planner-reset':'data-reset="all"')+'>Reset demo</button></div>':''}${storageWarning?'<div class="banner">'+esc(storageWarning)+'</div>':''}${content}<footer class="footer"><span>Made for curious minds, not finance degrees. · Educational examples in CAD.</span><span><button data-drawer="sources">Sources & assumptions</button> · <button ${isPlanner()?'data-planner-reset':'data-reset="all"'}>Reset ${isPlanner()?'planner':mode==='demo'?'demo lessons':'all lesson progress'}</button></span></footer></main></div>`}
function dashboard(){return `<section class="intro"><div><div class="eyebrow">LESS STRESS. MORE KNOW-HOW.</div><h1>Good things start with a little know-how.</h1><p>Your money questions have a place here. Pick a topic and get curious.</p></div><div class="session-chip"><div class="avatar-stack"><span>👩🏽</span><span>🧑🏻</span><span>👨🏾</span></div>Better learned together</div></section><section class="hero"><div class="hero-copy"><div class="eyebrow">✦ SMALL LESSONS. REAL-LIFE SKILLS.</div><h2>Big money energy.<br><em>Zero finance degree.</em></h2><p>From your first budget to your future plans.<br>Pick a topic. Learn by doing. Start anywhere.</p><button class="primary" data-explore>Find your first side quest <span>↘</span></button></div>${art()}</section><section class="planner-tool-teaser"><span aria-hidden="true">◉</span><div><div class="eyebrow">TOOLS FOR REAL LIFE · NO LESSON REQUIRED</div><h2>Put your money plan into motion.</h2><p>Estimate take-home pay, build your own budget and see where every dollar goes.</p></div><button class="primary" data-planner-open>Open budget planner ↗</button></section><section id="modules"><div class="section-head"><h2>Choose your side quest</h2><span>${learningModules.length} standalone modules · No required order</span></div><div class="module-grid">${learningModules.map((m,i)=>{const n=completed(m),pct=Math.round(n/m.steps.length*100);return `<article class="module-card"><div class="card-art ${m.id}"><span class="tag">${['EVERYDAY MONEY','BORROWING BASICS','FUTURE YOU','CANADIAN ACCOUNTS','BIG DECISIONS'][i]??'NEW SIDE QUEST'}</span><span class="card-number">0${i+1}</span><span class="card-symbol" aria-hidden="true">${['🪴','💳','📈','🧭','🏡'][i]??'✦'}</span></div><div class="card-body"><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="meta"><span>◷ ${esc(m.duration)}</span><span>◎ Beginner friendly</span></div><div class="progress-track" role="progressbar" aria-label="${esc(m.title)} progress" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div><div class="card-action"><button data-module="${m.id}">${n===m.steps.length?'Revisit module':n?'Continue learning':'Let’s explore'}<span>↗</span></button></div><div class="status">${n?`${n} of ${m.steps.length} steps explored`:'A fresh start. You’ve got this.'}</div></div></article>`}).join('')}</div></section>${resourceModules.map(m=>`<section class="benefits-feature"><div class="benefits-art" aria-hidden="true">✳</div><div><div class="eyebrow">BEYOND YOUR SALARY · KNOW YOUR BENEFITS</div><h2>Your job may offer more than a paycheque.</h2><p>Explore CPP and EI, employer matching, health coverage and insurance. Learn what is public, what depends on your workplace, and what to ask HR.</p><div class="benefits-chips"><span>CPP & EI</span><span>Matching lab</span><span>Insurance explorer</span></div></div><button class="primary" data-module="${m.id}">${completed(m)?'Resume benefits':'Explore workplace benefits'} ↗</button></section>`).join('')}<div class="bottom-grid"><section class="workshop"><span>✳</span><div><h3>Make a learning night of it.</h3><p>Explore the modules together. Pause and return whenever you like.</p></div><button class="plain" data-workshop>Start guided route ↗</button></section><section class="tip"><span>☀</span><div><h3>One topic is a great place to start.</h3><p>Each module is its own mini adventure. You don’t need to do them all.</p></div></section></div>`}
function refreshExtended(m,s,name,input){const a=mp(m.id).activities[name]??{};const markup=renderFeatureActivity(name,a,money);if(!markup)return false;const template=document.createElement('div');template.innerHTML=markup;const outputGroups=['.tax-results','.debt-results','.benefit-results'];const grouped=outputGroups.some(selector=>template.querySelector(selector));for(const selector of (grouped?outputGroups:['.growth-chart','.stats','.lab-insight','.year-table','.comparison-table','.cost-breakdown'])){const fresh=template.querySelectorAll(selector),current=root.querySelectorAll('.activity '+selector);current.forEach((element,i)=>{if(fresh[i])element.replaceWith(fresh[i])})}if(input.type==='range'){const label=input.closest('.range-field');const strong=label?.querySelector('strong');if(strong)strong.textContent=input.value+strong.textContent.replace(/^-?[\d.,]+/,'')}return true}
function numberField(label,key,value,min=0,max=100000,step=1){return `<label class="field"><span>${label}</span><input type="number" data-value="${key}" value="${value}" min="${min}" max="${max}" step="${step}" aria-label="${label}"></label>`}
function activity(m,s){const name=s.activity||({budgeting:'budget',credit:'credit',investing:'investing'}[m.id]);const a=mp(m.id).activities[name]??={};
const extended=renderFeatureActivity(name,a,money);if(extended)return extended;
if(name==='budget'){const values={...initialBudget,...a.values},shock=!!a.shock,total=Object.values(values).reduce((x,y)=>x+y,0)+(shock?350:0),left=3200-total;return `<div class="activity"><div class="activity-head"><strong>Alex’s monthly budget</strong><span>Take-home pay: $3,200</span></div><div class="activity-content">${Object.entries(values).map(([k,v])=>numberField({housing:'Housing',utilities:'Utilities & phone',groceries:'Groceries',transport:'Transport',debt:'Debt payment',flexible:'Flexible spending',irregular:'Irregular expenses',savings:'Emergency savings'}[k],k,v)).join('')}<div class="stats"><div class="stat"><span>Allocated${shock?' + surprise':''}</span><strong>${money(total)}</strong></div><div class="stat ${left<0?'warn':'good'}">Remaining<strong>${money(left)}</strong></div><div class="stat">Unexpected expense<strong>${shock?'$350':'$0'}</strong></div></div><button class="plain" data-shock>${shock?'Remove surprise expense':'Plot twist: a $350 repair bill'}</button><p class="fineprint">Fictional example. Savings are an allocation, not an expense already spent. Choose how to rebalance; there is no single correct lifestyle budget.</p></div></div>`}
if(name==='credit'){const balance=a.balance??1000,apr=a.apr??20,payment=a.payment??50,r=repayment(balance,apr,payment);return `<div class="activity"><div class="activity-head"><strong>Fictional card statement</strong><span>Purchase APR: 20%</span></div><div class="activity-content"><div class="statement"><div>Statement date<b>October 1</b></div><div>Payment due<b>October 22</b></div><div>Statement balance<b>$1,000</b></div><div>Current balance (Oct 5)<b>$1,150</b></div><div>Minimum payment shown<b>$30</b></div><div>New purchases after statement<b>$150</b></div></div><p class="fineprint">This is a sample statement, not a universal minimum-payment rule. The current balance includes later purchases. Read the issuer’s terms for grace periods and transaction exceptions.</p><h3 style="font-size:15px;margin-top:25px">What if you carry a balance?</h3>${numberField('Starting balance ($)','balance',balance,0,100000)}${numberField('APR (%)','apr',apr,0,100,.1)}${numberField('Fixed monthly payment ($)','payment',payment,1,100000)}${r.error?`<div class="banner">${esc(r.error)}</div>`:`<div class="stats"><div class="stat">Time to repay<strong>${r.months} mo.</strong></div><div class="stat warn">Interest paid<strong>${money(r.interest)}</strong></div><div class="stat">Total repaid<strong>${money(r.total)}</strong></div></div>`}<p class="fineprint">Illustration: interest added monthly at APR ÷ 12, then a fixed payment. No new purchases or fees; last payment is capped. Actual issuers may calculate interest daily. This models carrying debt, not purchase grace periods.</p></div></div>`}
if(name==='fees'){const p=a.principal??1000,c=a.monthly??100,y=a.years??20,g=a.gross??5,f=a.fee??1.5;const low=futureValue(p,c,y,g,.2),high=futureValue(p,c,y,g,f),peak=Math.max(low,high,1);return `<div class="activity"><div class="activity-head"><strong>Small fees, long timelines</strong><span>Illustrative, not a forecast</span></div><div class="activity-content">${numberField('Starting amount ($)','principal',p,0,100000)}${numberField('Monthly contribution ($)','monthly',c,0,10000)}${numberField('Years','years',y,1,50)}${numberField('Assumed gross annual return (%)','gross',g,-50,30,.1)}${numberField('Comparison annual fee (%)','fee',f,0,10,.1)}<div class="bars">${[['0.2% annual fee',low],['Your comparison fee: '+f+'%',high]].map(([l,v])=>`<div><div class="bar-label"><span>${l}</span><strong>${money(v)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${v/peak*100}%"></div></div></div>`).join('')}</div><p class="fineprint">Both cases use identical gross returns. Monthly rate = (gross annual return − annual fee) ÷ 12; contributions arrive at month-end. Taxes and trading costs are excluded. Returns vary in reality, and can be negative. Lower fees do not make different investments equally risky.</p></div></div>`}
const scenario=a.scenario??'company';const sets={company:{label:'One company struggles',v:[-40,-5,-12],note:'A company-specific problem hits one stock hard. A broad fund has less exposure to that single company. Other assets may still fall.'},market:{label:'Markets fall together',v:[-28,-22,-45],note:'Diversification does not prevent market-wide losses. A broad fund can fall substantially too. Recovery is never guaranteed.'},rally:{label:'An optimistic year',v:[18,12,35],note:'Risky assets can rise sharply as well as fall. A good result in one invented scenario does not predict the next one.'}};const d=sets[scenario]??sets.company;return `<div class="activity"><div class="activity-head"><strong>Same $1,000. Different exposures.</strong></div><div class="activity-content"><div class="segments">${Object.entries(sets).map(([k,v])=>`<button data-scenario="${k}" class="${scenario===k?'active':''}">${v.label}</button>`).join('')}</div><div class="bars">${['One company’s stock','Broad stock ETF','Crypto asset'].map((l,i)=>`<div><div class="bar-label"><span>${l}</span><strong>${d.v[i]>0?'+':''}${d.v[i]}% · ${money(1000*(1+d.v[i]/100))}</strong></div><div class="bar-track"><div class="bar-fill ${d.v[i]<0?'negative':''}" style="width:${Math.abs(d.v[i])*2}%"></div></div></div>`).join('')}</div><p style="font-size:14px;line-height:1.8">${d.note}</p><p class="fineprint">Entirely invented scenarios, not forecasts, historical returns, or an ordering of which asset will perform best. Bars show the size of the percentage change; signs and balances show direction. Asset categories contain different risks.</p></div></div>`}
function stepNav(m,index){const sections=[...new Set(m.steps.map(s=>s.section).filter(Boolean))];const button=(x,i)=>`<button class="step-button ${i===index?'active':''} ${mp(m.id).steps[x.id]?.completed?'done':''}" data-step="${i}"><span class="num">${mp(m.id).steps[x.id]?.completed?'✓':i+1}</span>${esc(x.title)}</button>`;if(!sections.length)return m.steps.map(button).join('');return sections.map(section=>{const steps=m.steps.map((s,i)=>({s,i})).filter(x=>x.s.section===section);return `<details class="nav-section" ${m.steps[index].section===section?'open':''}><summary>${esc(section)}<small>${steps.filter(x=>mp(m.id).steps[x.s.id]?.completed).length}/${steps.length}</small></summary>${steps.map(x=>button(x.s,x.i)).join('')}</details>`}).join('')}
function lesson(m,index){const s=m.steps[index],p=sp(m,s),pct=Math.round(completed(m)/m.steps.length*100);mp(m.id).lastStep=index;mp(m.id).lastStepId=s.id;save();const type=s.type;return `<div class="lesson-heading"><button class="back" data-home>← All side quests</button><span class="pill">${playlist?'Guided workshop · ':''}${esc(m.duration)} · Standalone lesson</span></div><details class="mobile-module-nav"><summary>Browse this module’s lessons</summary>${stepNav(m,index)}</details><div class="lesson-layout"><section class="lesson-stage"><div class="stage-top"><span>${esc(m.title.toUpperCase())} · ${esc(type==='check'?'QUICK CHECK':type==='activity'?'TRY IT OUT':type==='recap'?'TAKE IT WITH YOU':'LET’S EXPLORE')}</span><span>${index+1} / ${m.steps.length}</span></div><div class="stage-content"><h1 tabindex="-1" id="lesson-title">${esc(s.title)}</h1>${s.section?'<div class="chapter-label">'+esc(s.section)+'</div>':''}<p class="body-copy">${esc(s.body)}</p>${s.facts?'<div class="definition-grid">'+s.facts.map(f=>'<article><h3>'+esc(f.term)+'</h3><p>'+esc(f.definition)+'</p></article>').join('')+'</div>':''}${index===0?`<ul class="objectives">${m.objectives.map(o=>'<li>'+esc(o)+'</li>').join('')}</ul>`:''}${type==='activity'?activity(m,s):''}${type==='discuss'?`<div class="discussion"><div class="eyebrow">PAUSE & TALK IT THROUGH</div><p>${esc(s.prompt)}</p><button class="plain" data-reveal>${p.revealed?'Hide explanation':'Reveal the explanation →'}</button>${p.revealed?'<div class="reveal">'+esc(s.answer)+'</div>':''}</div>`:''}${type==='check'?`<div class="eyebrow" style="margin-top:25px">DISCUSS, THEN CHOOSE TOGETHER</div>${s.options.map((o,i)=>`<button class="option ${p.answer===i?'selected':''} ${p.revealed&&i===s.correct?'correct':''} ${p.revealed&&p.answer===i&&i!==s.correct?'wrong':''}" data-answer="${i}"><span class="letter">${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}<button class="primary" style="margin-top:15px" data-check ${p.answer===undefined?'disabled':''}>${p.revealed?'Discuss another answer':'Check our reasoning →'}</button>${p.revealed?`<div class="reveal" role="status"><strong>${p.answer===s.correct?'That’s the idea.':'Good question—let’s unpack it.'}</strong><br>${esc(s.rationales?.[p.answer]||s.answer)}</div>`:''}`:''}${type==='recap'?`<div class="module-complete"><h3>One more skill in your pocket. ✦</h3><p>What is one small thing you’ll try next? Discuss together, then mark this module complete.</p><button class="primary" data-complete>Complete this side quest ✓</button></div>`:''}</div><div class="lesson-nav"><button class="plain" data-prev ${index===0?'disabled':''}>← Back</button><span>${pct}% explored · no rush</span><button class="primary" data-next>${index===m.steps.length-1?'Back to modules':'Next step →'}</button></div></section><aside class="step-list"><h3>Your ${esc(m.title.toLowerCase())} quest</h3><div class="progress-track"><i style="width:${pct}%"></i></div><div style="margin-top:13px">${stepNav(m,index)}</div><details class="notes"><summary>Facilitator notes</summary><p>${esc(s.notes||'Invite a prediction before revealing. Ask: what changes your answer? Keep the discussion welcoming; no personal financial disclosures are needed.')}</p></details><button class="plain" style="margin-top:18px;width:100%" data-reset="${m.id}">Restart this module</button></aside></div><details class="notes mobile-notes"><summary>Facilitator notes</summary><p>${esc(s.notes||'Invite a prediction, then discuss the explanation. No personal disclosures needed.')}</p></details><div style="margin-top:15px"><button class="plain" data-reset="${m.id}">Reset ${esc(m.title.toLowerCase())} progress</button> <button class="plain" data-drawer="sources">Lesson sources ↗</button></div>`}
function sourcesForCurrentLesson(){const m=route().m;if(isPlanner())return [...new Map(plannerSources.map(s=>[s.url,s])).values()];const selected=m?sources.filter(s=>m.sourceIds.includes(s.id)):sources;return [...new Map(selected.map(s=>[s.url,s])).values()]}
function drawerHTML(){return `<div class="drawer-backdrop" data-close-backdrop><section class="drawer" role="dialog" aria-modal="true" aria-label="${drawer==='glossary'?'Glossary':'Sources and assumptions'}"><div class="drawer-head"><h2>${drawer==='glossary'?'A little less jargon.':'Sources & assumptions'}</h2><button class="plain" data-close aria-label="Close drawer">✕</button></div>${drawer==='glossary'?'<label class="glossary-search">Find a definition<input type="search" placeholder="Try MER, index, dividend…" data-glossary-search></label>'+glossary.map(x=>`<article><h3>${esc(x.term)}</h3><p>${esc(x.definition)}</p></article>`).join(''):`<p class="body-copy" style="font-size:14px">Canadian financial basics, grounded in public education sources. Examples are fictional and explain concepts rather than recommend products.</p>${sourcesForCurrentLesson().map(s=>`<article><h3>${esc(s.publisher)}</h3><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></article>`).join('')}<article><h3>Calculator assumptions</h3><p>Repayment: monthly interest at APR/12 before each payment, with no fees or new spending. Fee comparison: monthly compounding using (gross annual return − annual fee)/12; month-end contributions, no tax. New account/tax, retirement, debt and benefits calculators show their conventions and exclusions beside the controls. Tax models use 2026 rules, with federal-only or Ontario coverage. CPP/EI payroll uses standard 2026 outside-Quebec employment. Rates and outcomes are teaching estimates. Source review: October 2026.</p></article><article><h3>Your progress</h3><p>Saved on this browser for this shared session, not separately by person. Browser clearing or changing devices can remove progress. No financial information is sent to a server.</p></article>`}</section></div>`}
function render(){const {m,index}=route();root.innerHTML=shell(isPlanner()?renderPlanner(mode):m?lesson(m,index):dashboard(),isPlanner()?{id:'planner',title:'Budget planner'}:m)+(drawer?drawerHTML():'')+(modal?`<div class="modal-wrap"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="reset-title"><h2 id="reset-title">Reset ${modal==='all'?'all progress':esc(modules.find(m=>m.id===modal)?.title)+' progress'}?</h2><p>${modal==='all'?'Reset all '+mode+' progress on this browser?':`Reset ${esc(modules.find(m=>m.id===modal)?.title)}? Your other modules will keep their progress.`}</p><div class="modal-actions"><button class="plain" data-cancel>Keep learning</button><button class="primary" data-confirm>Reset progress</button></div></section></div>`:'');bind();if(isPlanner())bindPlanner({mode,onRender:render,root});if(drawer||modal){root.querySelector('[role="dialog"] button')?.focus()}}
function bind(){root.querySelectorAll('[data-planner-open]').forEach(e=>e.onclick=()=>{playlist=false;location.hash='/planner';if(isPlanner())render();window.scrollTo(0,0)});root.querySelectorAll('[data-home]').forEach(e=>e.onclick=()=>{playlist=false;go()});root.querySelectorAll('[data-module]').forEach(e=>e.onclick=()=>{playlist=false;const id=e.dataset.module;go(id,resumeIndex(id))});root.querySelector('[data-explore]')?.addEventListener('click',()=>document.querySelector('#modules').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}));root.querySelector('[data-workshop]')?.addEventListener('click',()=>{playlist=true;go(learningModules[0].id,0)});root.querySelectorAll('[data-drawer]').forEach(e=>e.onclick=()=>{drawer=e.dataset.drawer;render()});root.querySelector('[data-glossary-search]')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();root.querySelectorAll('.drawer article').forEach(a=>a.hidden=!(q.length<=3?(a.querySelector('h3').textContent.toLowerCase()+' '+a.querySelector('p').textContent.toLowerCase()).split(/[^a-z0-9]+/).includes(q)||!q:a.textContent.toLowerCase().includes(q)))});root.querySelector('[data-close]')?.addEventListener('click',()=>{drawer=null;render()});root.querySelector('[data-close-backdrop]')?.addEventListener('click',e=>{if(e.target===e.currentTarget){drawer=null;render()}});root.querySelector('[data-demo]')?.addEventListener('click',()=>{mode=mode==='demo'?'workshop':'demo';storageWarning='';state=load();try{sessionStorage.setItem('msq-mode',mode)}catch{}render()});root.querySelectorAll('[data-reset]').forEach(e=>e.onclick=()=>{drawer=null;modal=e.dataset.reset;render()});root.querySelector('[data-cancel]')?.addEventListener('click',()=>{modal=null;render()});root.querySelector('[data-confirm]')?.addEventListener('click',()=>{if(modal==='all'){state=empty();save();modal=null;go()}else{const id=modal;delete state.modules[id];save();modal=null;go(id,0)}});const {m,index}=route();if(!m)return;const s=m.steps[index],p=sp(m,s);root.querySelector('[data-prev]')?.addEventListener('click',()=>{if(index>0)go(m.id,index-1)});root.querySelector('[data-next]')?.addEventListener('click',()=>{if(s.type!=='recap')p.completed=true;save();if(index<m.steps.length-1)go(m.id,index+1);else go()});root.querySelectorAll('[data-step]').forEach(e=>e.onclick=()=>go(m.id,+e.dataset.step));root.querySelector('[data-reveal]')?.addEventListener('click',()=>{p.revealed=!p.revealed;if(p.revealed)p.completed=true;save();render()});root.querySelectorAll('[data-answer]').forEach(e=>e.onclick=()=>{p.answer=+e.dataset.answer;p.revealed=false;save();render()});root.querySelector('[data-check]')?.addEventListener('click',()=>{if(p.revealed){p.revealed=false;p.answer=undefined}else{p.revealed=true;p.completed=true}save();render()});root.querySelector('[data-complete]')?.addEventListener('click',()=>{p.completed=true;save();if(playlist&&learningModules.indexOf(m)>=0&&learningModules.indexOf(m)<learningModules.length-1)go(learningModules[learningModules.indexOf(m)+1].id,0);else{playlist=false;go()}});const name=s.activity||({budgeting:'budget',credit:'credit',investing:'investing'}[m.id]);root.querySelectorAll('[data-value]').forEach(e=>e.oninput=()=>{if(!e.checkValidity()||e.value.trim()===''||!Number.isFinite(+e.value)){e.reportValidity();return}const a=mp(m.id).activities[name]??={};if(name==='budget'){a.values={...initialBudget,...a.values,[e.dataset.value]:+e.value}}else a[e.dataset.value]=+e.value;const key=e.dataset.value;save();if(!refreshExtended(m,s,name,e)){render();root.querySelector('[data-value="'+key+'"]')?.focus()}});root.querySelector('[data-shock]')?.addEventListener('click',()=>{const a=mp(m.id).activities[name]??={};a.shock=!a.shock;save();render()});root.querySelectorAll('[data-choice]').forEach(e=>e.onchange=()=>{const a=mp(m.id).activities[name]??={};a[e.dataset.choice]=e.value;save();render()});root.querySelectorAll('[data-product]').forEach(e=>e.onclick=()=>{const a=mp(m.id).activities[name]??={};a.product=e.dataset.product;delete a.mer;save();render()});root.querySelectorAll('[data-scenario]').forEach(e=>e.onclick=()=>{const a=mp(m.id).activities[name]??={};a.scenario=e.dataset.scenario;save();render()})}
window.addEventListener('hashchange',()=>{render();document.querySelector('#lesson-title')?.focus({preventScroll:true})});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(drawer||modal)){drawer=null;modal=null;render()}if(e.key==='Tab'&&(drawer||modal)){const d=root.querySelector('[role="dialog"]'),els=[...d.querySelectorAll('button,a[href],input,summary')].filter(x=>!x.disabled&&x.getClientRects().length); const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});render();
